const workspacesExist = `-- name: WorkspacesExist :one
SELECT NOT EXISTS (SELECT 1 FROM unnest($1::text[]) n
    WHERE NOT EXISTS (SELECT 1 FROM workspaces w WHERE w.name = n))
`

func (q *Queries) WorkspacesExist(ctx context.Context, names []string) (bool, error) {
	row := q.db.QueryRow(ctx, workspacesExist, names)
	var not_exists bool
	err := row.Scan(&not_exists)
	return not_exists, err
}
